	["Choque: daño instantáneo."] = "충격: 즉시 피해.",
	["Cierra una pestaña para abrir esta guía."] = "이 가이드를 열려면 탭 하나를 닫으세요.",
	["Cierra una pestaña para abrir otra."] = "다른 것을 열려면 탭 하나를 닫으세요.",
