	["Clic: la flecha te lleva aquí."] = "클릭: 화살표가 이곳으로 안내합니다.",
	["Clic: la flecha te lleva. Clic derecho: ya no mostrarla."] = "클릭: 화살표가 안내합니다. 오른쪽 클릭: 더 이상 표시 안 함.",
	["Clic: la lista de pasos. Rueda: mirar otros pasos sin cambiar nada."] = "클릭: 단계 목록. 휠: 아무것도 바꾸지 않고 다른 단계 보기.",
	["Clic: ocultarlo en el modelo."] = "클릭: 모델에서 숨기기.",
