	["No te alcanza"] = "돈 부족",
	["No tienes misiones para este plan con ese filtro."] = "그 필터로는 이 계획에 넣을 퀘스트가 없습니다.",
	["No tienes puntos libres. El siguiente talento del plan (%s) te toca en el nivel %d."] = "남은 포인트가 없습니다. 계획의 다음 특성(%s)은 %d레벨에 찍습니다.",
	["No tienes un sello puesto: ponte uno."] = "문장이 없습니다. 문장을 거세요.",
