	["Ocultas como en el juego, reveladas, o reveladas con un tono más frío para saber dónde no has estado."] = "게임처럼 숨기거나, 표시하거나, 가 보지 않은 곳을 알 수 있게 차가운 색조로 표시합니다.",
	["Oculto en el modelo."] = "모델에서 숨김.",
