	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "지도 키로 열려면 아래의 «지도 키로 Alfa 지도 열기»를 켜세요.",
	["Para alguien de tu hermandad, agrega su rango."] = "같은 길드원이면 길드 등급을 추가합니다.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Alfa는 아이템마다 세 가지 방법을 비교합니다: 상인에게 팔기, 경매장에 올리기, 다른 것으로 바꾸기(아는 제조법이나 마력 추출로).",
	["Para comprar espacio, habla con un banquero."] = "공간을 사려면 은행원과 대화하세요.",
	["Para conservar"] = "남겨 둘 것",
	["Para depositar, habla con un banquero."] = "보관하려면 은행원과 대화하세요.",
