	["Primero crea una ruta: /alfa recoleccion ruta"] = "먼저 경로를 만드세요: /alfa recoleccion ruta",
	["Primero defensa: paras muchos más golpes y descansas menos."] = "방어 우선: 무기 막기가 훨씬 늘고 쉬는 시간이 줄어듭니다.",
