	["Préndelo para ver jefes, botín, misiones y consejos de cada mazmorra."] = "켜면 던전마다 우두머리, 전리품, 퀘스트, 공략을 볼 수 있습니다.",
	["Puede controlar la mente de un jugador: no lo ataquen, esperen a que se le pase."] = "플레이어의 정신을 지배할 수 있습니다. 그 플레이어를 공격하지 말고 풀릴 때까지 기다리세요.",
	["Puede convertir a alguien en huargo: no ataquen a ese jugador, se le pasa solo."] = "플레이어를 늑대인간으로 바꿀 수 있습니다. 그 플레이어를 공격하지 마세요. 저절로 풀립니다.",
	["Puede dormir a alguien del grupo: sigue peleando, se despierta solo."] = "파티원 한 명을 재울 수 있습니다. 계속 싸우세요. 저절로 깨어납니다.",
	["Puede dormir a alguien y golpear a todos los que están cerca."] = "한 명을 재우고 주변 모두를 때릴 수 있습니다.",
	["Puede lanzarte por los aires con un gancho: regresa rápido para que no vaya tras quien cura."] = "어퍼컷으로 날려 보냅니다. 치유 전담에게 가지 않도록 빨리 돌아오세요.",
	["Puede pisotear a los que pelean cuerpo a cuerpo: mantén su vida alta."] = "근접 플레이어를 짓밟을 수 있습니다. 근접 플레이어의 생명력을 높게 유지하세요.",
	["Puedes Cargar en actitud defensiva: empiezas a tanquear sin cambiar de actitud."] = "방어 태세에서 돌진할 수 있어, 태세를 바꾸지 않고 방어 전담을 시작합니다.",
	["Puedes cambiar cada tramo."] = "구간마다 바꿀 수 있습니다.",
	["Puedes tomarla"] = "받을 수 있음",
	["Puedes usarlo"] = "사용 가능",
	["Puedes vender %d cosas por unos %s."] = "%d개를 약 %s에 팔 수 있습니다.",
	["Puedes vender %s (unos %s)."] = "%s 판매 가능(약 %s).",
	["Puedo usar"] = "사용 가능한 것만",
	["Pulsa %s para lanzar. Cuando el corcho se hunda, pulsa %s otra vez para recoger."] = "%s 키를 눌러 던지세요. 찌가 가라앉으면 %s 키를 다시 눌러 낚아 올리세요.",
	["Pulsa Guiarme y la flecha te lleva de parada en parada desde la más cercana."] = "'안내 시작'을 누르면 가장 가까운 곳부터 경유지를 차례로 안내합니다.",
