	["Quedan %d casillas libres. Puedes vender %s (unos %s)."] = "빈칸이 %d칸 남았습니다. %s 판매 가능(약 %s).",
	["Quedan %s"] = "%s 남음",
	["Quedó sin pasos: agrega tramos o recalcula."] = "단계가 없습니다. 구간을 추가하거나 다시 계산하세요.",
	["Quema al enemigo un rato."] = "한동안 적을 불태웁니다.",
