	["Quienes comparten su ubicación contigo. Un clic en su marca y la flecha te lleva."] = "나와 위치를 공유하는 사람들입니다. 표시를 클릭하면 화살표가 안내합니다.",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras ni por canales públicos."] = "Alfa를 쓰며 공유하는 사람은 지도에서 나를 보고 따라올 수 있고, 나도 그렇습니다. 지역, 위치, 레벨, 직업을 움직일 때는 10초마다(가만히 있으면 4분마다) 보내며, 던전 안이나 공개 채널로는 절대 보내지 않습니다.",
