	["Recomienda el camino que te deja más oro, si gana por lo menos un 10 % a venderlo. Si nada da oro, te dice que lo guardes. Alfa nunca vende ni compra por ti."] = "상인 판매보다 최소 10% 이상 더 벌 수 있을 때, 골드를 가장 많이 버는 방법을 추천합니다. 골드가 되는 방법이 없으면 보관하라고 알려 줍니다. Alfa는 절대 대신 팔거나 사지 않습니다.",
