	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "공격이 두 번째 적에게도 닿습니다. 두 마리가 몰려올 때 딱 좋습니다.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "외침이 더 멀리 닿고 더 오래 지속되어 파티 전체를 돕습니다.",
