	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "공격을 받아 내며 파티를 지킵니다. 방패가 필요합니다.",
	["Ubicación de %s"] = "%s 님의 위치",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "양손에 무기 하나씩과 넘치는 분노: 파티에서 가장 큰 피해를 줍니다.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "큰 양손 무기와 출혈을 일으키는 공격. 가장 쉬운 레벨업 방법입니다.",
	["Un aturdimiento cuando lo necesites."] = "필요할 때 쓰는 기절 기술입니다.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "세션마다 Alfa를 처음 열 때 게임 자체의 늑대 울음소리.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "우두머리와 처치한 수를 알리고, 클릭 한 번으로 공략을 엽니다.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "상황에 따라 켜지는 기술이 활성화되면 짧게 알립니다. 예: 적이 회피한 뒤의 제압.",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "새 우두머리를 처치하면 알리고, 클릭 한 번으로 전리품을 엽니다.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "알림과 가방 안의 띠로 팔 것, 남겨 둘 것, 찾아갈 상인을 알려 주고, 클릭 한 번으로 잡동사니를 표시합니다.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "품질 색상의 테두리: 초록, 파랑, 보라...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "추천 기술이 있는 단축바 버튼에 깜박이는 초록 테두리를 띄워 빨리 찾게 합니다.",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "클릭 한 번이면 나, 파티, 마커, 가이드의 다음 단계만 남습니다.",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "내 생명력과 내 직업에 가장 중요한 능력치를 보여 주는 옮길 수 있는 작은 상자입니다. 전투 중에는 게임이 일부 수치를 숨기므로 마지막으로 읽은 값이 남습니다.",
	["Un enemigo"] = "적 하나",
	["Un fondo del color de tu clase bajo tu nombre."] = "내 이름 아래에 직업 색상 배경을 깝니다.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "위협 수준이 엄청난 강력한 방패 공격입니다.",
	["Un golpe más para gastar ira."] = "분노를 쓸 공격이 하나 더 생깁니다.",
	["Un golpe nuevo y fuerte para tu barra."] = "단축바에 넣을 새롭고 강한 공격입니다.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "어려운 몬스터를 상대로 피해가 크게 늘고, 공포에서도 풀려납니다.",
	["Un hechizo de tus barras tiene un rango viejo"] = "단축바에 낮은 레벨 주문이 있음",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "퀘스트에 쓰이는 아이템에 금색 테두리를 표시합니다(퀘스트를 시작하는 아이템은 «!»).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "원하는 아이템: Alfa가 먼저 필요한 것까지 포함해 얻는 길을 만듭니다.",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "다음 단계들이 안내할 곳에 번호가 붙은 작은 핀을 표시합니다.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "치명타, 회피, 방어도가 조금씩 늘어납니다.",
	["Un poco de vida de vuelta después de críticos."] = "치명타 뒤에 생명력을 조금 회복합니다.",
	["Un poco más de defensa."] = "방어 숙련이 조금 늘어납니다.",
	["Un poco más de ira al cargar."] = "돌진할 때 분노가 조금 더 늘어납니다.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "다음 줄을 열고 조금 덜 빗나가게 하는 1포인트.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "내 레벨에 맞는 퀘스트를 주는 NPC 머리 위에 느낌표를 표시합니다.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "완료한 퀘스트를 받는 NPC 머리 위에 물음표를 표시합니다.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "플레이에 필요한 모든 것을 담은 하나의 애드온: 화살표와 경로가 있는 단계별 가이드, 지도, 가방, 빌드, 클릭 치유, 채집, 던전, 낚시, 거래. 모두 같은 스타일입니다.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "세게 때리는 방어 전담: 추가 방어를 조금 포기하는 대신, 피해를 많이 주는 파티를 위해 위협 수준을 많이 쌓습니다. 경험이 조금 있는 방어 전담용입니다.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "지금 쓸 기술을 보여 주는 아이콘입니다. 보여 주기만 하고 절대 대신 누르지 않습니다.",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "크게 보이는 추천 행동 하나와 클릭 몇 번이면 되는 내 길.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "우두머리가 곧 쓸 공격과 각각 남은 시간을 보여 주는 막대입니다. 언제 움직이거나 방어할지 알 수 있습니다.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "문자열 하나에 빌드 전체가 담깁니다. 복사해서 보내면 상대가 붙여 넣습니다.",
	["Una categoría…"] = "분류 하나…",
	["Una cuenta de prueba no puede compartir"] = "체험판 계정은 공유할 수 없음",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "가방에서 내 전문화에 향상이 되는 아이템마다 초록색 화살표를 표시합니다.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "내 직업과 레벨 기준으로 지금 착용한 것보다 좋은 장비에 초록 화살표를 표시합니다.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "연두색 띠로 오고 있는 치유량을 보여 줍니다.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "내 레벨과 지역에 맞는 가이드, 또는 나만의 퀘스트 경로.",
	["Una línea debajo del aviso con lo que pasó."] = "알림 아래에 무슨 일이 있었는지 한 줄로 표시합니다.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "적이 그 파티원을 노리면 위쪽에 빨간 선으로 알려 줍니다.",
	["Una mano"] = "한손",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "회색 아이템과 잡동사니로 표시한 것에 동전을 표시합니다.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Empieza con una plantilla."] = "경로는 구간으로 이루어진 트리입니다. 경험치, 골드, 직업 퀘스트, 재료, 아이템. 템플릿으로 시작하세요.",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "경로를 만들려면 내 숙련도로 채집할 수 있는 장소가 3곳 이상 필요합니다. 아래에서 다른 종류나 자원을 고르거나 여기서 채집하세요. Alfa가 찾은 지점을 모두 기록합니다.",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "내 숙련도에 맞는 최고의 장소를 도는 경로, 중간에 경험치 퀘스트 몇 개.",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "내 숙련도로 채집할 수 있는 %d곳을 짧은 순환 경로로 잇고 지도에 그린 뒤, 화살표로 경유지를 차례로 안내합니다.",
	["Uno menos"] = "하나 빼기",
	["Uno más"] = "하나 더",
	["Usa %s"] = "%s 사용",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "우두머리가 세게 때릴 때 방패 막기를 쓰세요.",
	["Usa Deseo de muerte al empezar contra un jefe."] = "우두머리 전투를 시작할 때 죽음의 소원을 쓰세요.",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "죽음의 소원은 쉬운 몬스터가 아니라 어려운 몬스터에게 쓰세요.",
	["Usa Golpe mortal sobre todo contra sanadores."] = "죽음의 일격은 특히 치유 전담에게 쓰세요.",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "적이 두 마리 이상 모여 있으면 휩쓸기 일격을 쓰세요.",
	["Usa Ira rabiosa para romper miedos."] = "공포를 풀려면 광전사의 격노를 쓰세요.",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "복수가 빛날 때마다 쓰고, 방어구 가르기로 위협 수준을 더하세요.",
	["Usa Transfusión de vida para recuperar maná a cambio de vida."] = "생명력 전환으로 생명력을 대가로 마나를 회복하세요.",
	["Usa a tu demonio para frenar al monstruo mientras lanzas."] = "주문을 시전하는 동안 악마로 몬스터를 붙잡아 두세요.",
	["Usa el juicio y vuelve a poner tu sello enseguida."] = "심판을 쓰고 곧바로 문장을 다시 거세요.",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "추천 기술 버튼에 게임 자체의 강조 효과를 씁니다.",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "몬스터가 하나면 표범 변신, 여럿이 오면 곰 변신을 쓰세요.",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "주력 공격으로 연계 점수를 모으고 마무리 기술에 쓰세요.",
	["Usa tu varita cuando quieras ahorrar maná."] = "마나를 아끼고 싶을 때는 마법봉을 쓰세요.",
	["Usa tus hechizos de control si se te juntan dos monstruos."] = "몬스터 두 마리가 몰려오면 군중 제어 주문을 쓰세요.",
	["Usa un arma lenta y fuerte: tus mejoras de arma pegan con cada golpe."] = "느리고 강한 무기를 쓰세요. 무기 강화 효과가 공격마다 들어갑니다.",
	["Usar"] = "사용",
	["Usar el banco de Alfa"] = "Alfa 은행 사용",
	["Usar esta"] = "이것 사용",
	["Usar esta guía"] = "이 가이드 사용",
	["Usar la base de datos incluida"] = "기본 제공 데이터베이스 사용",
	["Usar la pesca de Alfa"] = "Alfa 낚시 사용",
	["Usar las bolsas de Alfa"] = "Alfa 가방 사용",
	["Usar los marcos de Alfa"] = "Alfa 프레임 사용",
	["Usar los pesos de mi build"] = "내 빌드의 가중치 사용",
	["Usar mis talentos de ahora"] = "현재 특성 사용",
	["Usar siempre la prioridad de Alfa"] = "항상 Alfa 우선순위 사용",
	["Usar también en los marcos de Blizzard"] = "블리자드 프레임에서도 사용",
	["Usarlo"] = "사용",
	["Usas las bolsas del juego"] = "게임 가방 사용 중",
	["Uso: /alfa comercio precio <enlace del objeto>"] = "사용법: /alfa comercio precio <아이템 링크>",
	["Uso: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]"] = "사용법: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]",
	["Uso: /alfa silenciar <número>, /alfa silenciar quitar <número>, /alfa silenciar borrar."] = "사용법: /alfa silenciar <번호>, /alfa silenciar quitar <번호>, /alfa silenciar borrar.",
	["Valor de bloqueo"] = "방패 피해 흡수량",
	["Varios"] = "기타",
	["Varios enemigos cerca: golpéalos a todos a la vez."] = "가까이에 적이 여럿입니다. 한꺼번에 공격하세요.",
	["Varios enemigos: consagra el suelo bajo ti."] = "적이 여럿입니다. 발밑에 신성화를 쓰세요.",
	["Varios enemigos: el disparo alcanza a varios."] = "적이 여럿입니다. 사격이 여러 적을 맞힙니다.",
	["Varios enemigos: el rayo salta entre ellos."] = "적이 여럿입니다. 번개가 적 사이를 튑니다.",
	["Varios enemigos: golpéalos a todos."] = "적이 여럿입니다. 모두 공격하세요.",
	["Varios enemigos: tus golpes alcanzan a otro más."] = "적이 여럿입니다. 공격이 적 하나를 더 칩니다.",
	["Varita"] = "마법봉",
	["Vas tras %s"] = "%s 님 추적 중",
	["Veces completada"] = "완료 횟수",
	["Veces completadas"] = "완료 횟수",
	["Velocidad"] = "속도",
	["Vence a este jefe para descubrir su nombre y su botín."] = "이 우두머리를 처치하면 이름과 전리품이 공개됩니다.",
	["Vence a sus jefes para ver lo que sueltan, o apaga el modo historia en Ajustes."] = "우두머리를 처치해 떨어뜨리는 것을 보거나, 설정에서 스토리 모드를 끄세요.",
	["Vencido"] = "처치함",
	["Vendas para curarte sin gastar maná ni esperar: imprescindible para todos."] = "마나도 쓰지 않고 기다리지도 않고 자신을 치유하는 붕대: 모두에게 꼭 필요합니다.",
	["Vende"] = "판매",
	["Vende lo gris con cualquier vendedor o tira algo que ya no uses."] = "회색 아이템을 아무 상인에게나 팔거나, 더 이상 쓰지 않는 것을 버리세요.",
	["Vendedor"] = "상인",
	["Vendedores"] = "상인",
	["Vender"] = "상인 판매",
	["Vender %d"] = "상인 판매 %d",
	["Vender la chatarra"] = "잡동사니 팔기",
	["Vender la chatarra (%d)"] = "잡동사니 팔기 (%d)",
	["Vendiste %d objetos de chatarra por unos %s."] = "잡동사니 %d개를 약 %s에 팔았습니다.",
	["Venenos"] = "독",
	["Venenos y críticos: matas rápido, sobre todo atacando por la espalda."] = "독과 치명타: 특히 등 뒤에서 공격하면 빨리 처치합니다.",
	["Ventana de guía oculta. Escribe /alfa guia para volver a verla."] = "가이드 창을 숨겼습니다. /alfa guia를 입력하면 다시 나타납니다.",
	["Ventana de guía propia"] = "자체 가이드 창",
